    <script>
        function toggleLike(el){
            let text = el.textContent;
            if(text.includes('赞')){
                el.textContent = text.replace('赞','已赞');
                el.style.color = '#ff5a5f';
            }else{
                el.textContent = text.replace('已赞','赞');
                el.style.color = '#666';
            }
        }
    </script>
</body>
</html>

