<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>趣聊 - 动态详情</title>
    <style>
        body{font-family:Arial,sans-serif;background:#f5f5f5;margin:0;color:#333;}
        .navbar{background:#fff;padding:10px 20px;display:flex;align-items:center;box-shadow:0 2px 4px rgba(0,0,0,.1);}
        .navbar a{margin-right:20px;color:#333;text-decoration:none;font-weight:bold;}
        .navbar a:hover{color:#ff5a5f;}
        .container{max-width:800px;margin:auto;padding:20px;}
        .post-card{background:#fff;padding:20px;border-radius:8px;box-shadow:0 1px 3px rgba(0,0,0,.1);}
        .post-header{display:flex;align-items:center;margin-bottom:15px;}
        .avatar{width:50px;height:50px;border-radius:50%;background:#ccc;margin-right:10px;}
        .username{font-weight:bold;}
        .post-content{margin-bottom:15px;}
        .post-image{width:100%;max-height:500px;object-fit:cover;border-radius:6px;margin-bottom:15px;}
        .post-actions span{margin-right:20px;cursor:pointer;color:#666;}
        .post-actions span:hover{color:#ff5a5f;}
        .comments-section{margin-top:30px;}
        .comment{display:flex;margin-bottom:15px;}
        .comment .avatar{width:35px;height:35px;border-radius:50%;background:#bbb;margin-right:10px;}
        .comment .text{background:#eee;padding:8px 12px;border-radius:8px;max-width:70%;}
        .comment .text .username{font-weight:bold;margin-right:5px;}
        .add-comment{display:flex;margin-top:20px;}
        .add-comment input{flex:1;padding:8px;border:1px solid #ccc;border-radius:4px;margin-right:10px;}
        .add-comment button{background:#ff5a5f;color:#fff;border:none;padding:8px 12px;border-radius:4px;cursor:pointer;}
        .add-comment button:hover{background:#e04e52;}
        .footer{text-align:center;padding:20px;color:#777;font-size:14px;}
        @media(max-width:600px){
            .navbar{flex-direction:column;align-items:flex-start;}
            .navbar a{margin-bottom:5px;}
        }
    </style>
</head>
<body>
    <nav class="navbar">
        <a href="index.html">首页</a>
        <a href="profile.html">我的主页</a>
        <a href="signup.html">注册</a>
    </nav>
    <div class="container">
        <div class="post-card">
            <div class="post-header">
                <div class="avatar"></div>
                <div class="username">小明</div>
            </div>
            <div class="post-content">今天在咖啡店拍到了超好看的光影，分享给大家！</div>
            <img src="data:image/png;base64," alt="post image" class="post-image">
            <div class="post-actions">
                <span onclick="toggleLike(this)">👍 赞 28</span>
                <span>🔁 分享</span>
            </div>
        </div>

        <div class="comments-section">
            <h3>评论（5）</h3>
            <div class="comment">
                <div class="avatar"></div>
                <div class="text"><span class="username">阿华</span>好美的光影！</div>
            </div>
            <div class="comment">
                <div class="avatar"></div>
                <div class="text"><span class="username">小芳</span>我也想去那家咖啡店。</div>
            </div>
            <div class="comment">
                <div class="avatar"></div>
                <div class="text"><span class="username">大壮</span>下次一起去吧！</div>
            </div>

            <div class="add-comment">
                <input type="text" id="newComment" placeholder="写下你的评论...">
                <button onclick="addComment()">发送</button>
            </div>
        </div>
    </div>

    <footer class="footer">
        © 2026 趣聊. 保留所有权利。
    </footer>

    <script>
        function toggleLike(el){
            if(el.textContent.includes('已赞')){
                el.textContent = el.textContent.replace('已赞','赞');
                el.style.color = '#666';
            }else{
                el.textContent = el.textContent.replace('赞','已赞');
                el.style.color = '#ff5a5f';
            }
        }
        function addComment(){
            const input = document.getElementById('newComment');
            const text = input.value.trim();
            if(!text) return;
            const commentDiv = document.createElement('div');
            commentDiv.className = 'comment';
            commentDiv.innerHTML = `<div class="avatar"></div><div class="text"><span class="username">我</span>${text}</div>`;
            const section = document.querySelector('.comments-section');
            section.insertBefore(commentDiv, document.querySelector('.add-comment'));
            input.value = '';
        }
    </script>
</body>
</html>

