<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>趣聊 - 注册</title>
    <style>
        body{font-family:Arial,sans-serif;background:#f5f5f5;margin:0;color:#333;}
        .navbar{background:#fff;padding:10px 20px;display:flex;align-items:center;box-shadow:0 2px 4px rgba(0,0,0,.1);}
        .navbar a{margin-right:20px;color:#333;text-decoration:none;font-weight:bold;}
        .navbar a:hover{color:#ff5a5f;}
        .container{max-width:500px;margin:auto;padding:40px 20px;}
        .card{background:#fff;padding:30px;border-radius:8px;box-shadow:0 1px 3px rgba(0,0,0,.1);}
        h2{text-align:center;margin-bottom:20px;}
        .field{margin-bottom:15px;}
        .field label{display:block;margin-bottom:5px;}
        .field input{width:100%;padding:8px;border:1px solid #ccc;border-radius:4px;}
        .submit{background:#ff5a5f;color:#fff;border:none;width:100%;padding:10px;border-radius:4px;font-size:16px;cursor:pointer;}
        .submit:hover{background:#e04e52;}
        .footer{text-align:center;padding:20px;color:#777;font-size:14px;margin-top:30px;}
        @media(max-width:600px){
            .navbar{flex-direction:column;align-items:flex-start;}
            .navbar a{margin-bottom:5px;}
        }
    </style>
</head>
<body>
    <nav class="navbar">
        <a href="index.html">首页</a>
        <a href="profile.html">我的主页</a>
        <a href="signup.html">注册</a>
    </nav>
    <div class="container">
        <div class="card">
            <h2>立即加入趣聊</h2>
            <form onsubmit="return false;">
                <div class="field">
                    <label for="username">用户名</label>
                    <input type="text" id="username" placeholder="请输入用户名" required>
                </div>
                <div class="field">
                    <label for="email">邮箱</label>
                    <input type="email" id="email" placeholder="example@domain.com" required>
                </div>
                <div class="field">
                    <label for="password">密码</label>
                    <input type="password" id="password" placeholder="设置密码" required>
                </div>
                <button class="submit">注册账号</button>
            </form>
        </div>
    </div>

    <footer class="footer">
        © 2026 趣聊. 保留所有权利。
    </footer>
</body>
</html>
